#pragma once
#include <QJsonArray>
#include <QJsonDocument>
#include <QJsonObject>
#include <QRegularExpression>
#include <QDateTime>
#include <QSet>
#include <QMap>
#include <stdexcept>
namespace stockResearch {
inline void need(bool b,const QString& why){if(!b)throw std::runtime_error(why.toStdString());}
inline QByteArray bytes(const QJsonValue& v){return v.isArray()?QJsonDocument(v.toArray()).toJson(QJsonDocument::Compact):QJsonDocument(v.toObject()).toJson(QJsonDocument::Compact);}
inline void identity(const QString& id){need(QRegularExpression("^(SH|SZ|BJ):(stock|etf|index):[0-9]{6}$").match(id).hasMatch(),"必须明确完整市场、证券类型和六位代码");auto parts=id.split(':');auto market=parts[0],type=parts[1],code=parts[2];bool ok=type=="stock"?(market=="SH"?code.startsWith('6')||code.startsWith('9'):market=="SZ"?code.startsWith('0')||code.startsWith('3'):code.startsWith('4')||code.startsWith('8')||code.startsWith("92")):type=="etf"?(market=="SH"?code.startsWith('5'):market=="SZ"&&(code.startsWith("15")||code.startsWith("16"))):(market=="SH"?code.startsWith("000"):market=="SZ"&&code.startsWith("399"));need(ok,"市场/证券类型与代码不一致，未猜测身份");}
inline QJsonObject bundle(const QString& id,const QJsonObject& input){identity(id);need(input["id"]==id,"宿主资料与所选完整证券身份不一致");need(bytes(input).size()<=16*1024*1024,"证券资料超过16MB，请分批研究");if(input.contains("companyProfile")){auto p=input["companyProfile"].toObject();need(p["schema"]=="native-stock-company-profile/v1"&&p["id"]==id,"公司主营资料与研究完整证券身份不一致");}if(input.contains("documents")){need(input["documents"].isArray(),"证据必须为数组");QSet<QString> ids;for(auto v:input["documents"].toArray()){auto d=v.toObject();need(v.isObject()&&!d["id"].toString().isEmpty()&&d["text"].isString()&&d["text"].toString().size()<=600000,"证据原记录缺失或过长");need(!ids.contains(d["id"].toString()),"证据身份重复");ids.insert(d["id"].toString());}}return input;}
inline QJsonObject snapshot(const QString& key,const QString& id,const QJsonObject& input,const QString& note,const QString& capturedAt){need(!key.isEmpty()&&key.size()<=100,"快照ID无效");need(note.size()<=100000,"笔记过长");auto t=QDateTime::fromString(capturedAt,Qt::ISODateWithMs);need(t.isValid(),"本机保存时间无效");return {{"id",key},{"instrumentId",id},{"capturedAt",capturedAt},{"note",note},{"bundle",bundle(id,input)}};}
inline QJsonObject validate(const QString& kind,const QJsonObject& r){if(kind=="notes"){identity(r["id"].toString());need(r["text"].isString()&&r["text"].toString().size()<=100000&&r["revision"].isDouble()&&r["revision"].toDouble()>=1&&r["revision"].toDouble()==r["revision"].toInt(),"笔记字段/版本无效");return r;}need(kind=="snapshots","未知研究记录类型");auto valid=snapshot(r["id"].toString(),r["instrumentId"].toString(),r["bundle"].toObject(),r["note"].toString(),r["capturedAt"].toString());need(bytes(valid)==bytes(r),"快照字段与原记录不一致");return valid;}
inline QJsonObject decode(const QByteArray& input){need(input.size()<=32*1024*1024,"导入超过32MB");QJsonParseError error;auto d=QJsonDocument::fromJson(input,&error);need(error.error==QJsonParseError::NoError&&d.isObject(),"导入JSON无效");auto o=d.object();need(o["schema"]=="stock-research/v1","不支持的个股研究备份");for(auto k:{"notes","snapshots"}){need(o[k].isArray()&&o[k].toArray().size()<=10000,"备份数组缺失或超过10000条");QSet<QString> seen;for(auto v:o[k].toArray()){need(v.isObject(),"记录必须为对象");auto r=validate(k,v.toObject());need(!seen.contains(r["id"].toString()),"备份ID重复");seen.insert(r["id"].toString());}}return o;}
inline QJsonObject preview(const QJsonObject& incoming,const QJsonObject& current){QJsonObject inserts;QJsonArray conflicts;int duplicate=0;for(auto k:{"notes","snapshots"}){QJsonArray out;QMap<QString,QJsonObject> existing;for(auto v:current[k].toArray())existing[v.toObject()["id"].toString()]=v.toObject();for(auto v:incoming[k].toArray()){auto r=v.toObject(),old=existing.value(r["id"].toString());if(old.isEmpty())out.append(r);else if(bytes(old)==bytes(r))++duplicate;else conflicts.append(QString(k)+":"+r["id"].toString());}inserts[k]=out;}return {{"inserts",inserts},{"duplicates",duplicate},{"conflicts",conflicts}};}
inline QString pretty(const QJsonObject& o){return QString::fromUtf8(QJsonDocument(o).toJson());}
inline QString display(const QJsonValue& v){if(v.isNull()||v.isUndefined())return "未提供";if(v.isDouble())return QString::number(v.toDouble(),'g',15);if(v.isBool())return v.toBool()?"是":"否";return v.toString();}
inline QString overview(const QJsonObject& b){QString out="完整身份："+b["id"].toString()+" · "+b["name"].toString()+"\n";const auto q=b["quote"].toObject();out+="报价："+display(q["price"])+" · 涨跌幅（%）："+display(q["changePercent"])+"\n行情时点："+display(q["tradeDate"])+" "+display(q["tradeTime"])+"\n行情来源："+display(q["source"])+" · 缓存："+display(q["cached"])+"\n本机检查时点："+display(q["checkedAt"])+"\n行情原字段："+(q.isEmpty()?QString("不可得；未补0"):pretty(q))+"\n";for(auto k:{"day","minute","capitalDay","capitalMinute","capitalSnapshot"}){auto rows=b[k].toArray();auto meta=b[QString(k)+"Meta"].toObject();out+=QString(k)+"：本机覆盖 "+QString::number(rows.size())+" 点\n"+(meta.isEmpty()?QString("来源时点与覆盖元数据未提供"):pretty(meta))+"\n";}out+="主营 / 行业 / 标签（仅已有资料）：\n";for(auto k:{"industry","csrcIndustry","businessSummary","mainBusinessItems","tags","profile","news","watchlist","accountPositions","source","sourceUrl","fetchedAt","cached"}){if(!b.contains(k))out+=QString(k)+"：未提供\n";else {QJsonObject one{{k,b[k]}};out+=pretty(one);}}return out+"\n源时间分别显示；保存时间不是行情或资料时点。完整冻结原文\n"+pretty(b);}
}
